<section class="stats-grid three-cols">
<?php foreach ([['catalogo', 'Productos en catálogo', 'Catálogo general'], ['unidades', 'Existencias totales', 'Unidades en las sucursales consultadas'], ['bajo', 'Productos con stock bajo', 'Productos activos bajo el mínimo']] as [$campo, $nombre, $detalle]) : ?><article class="stat-card"><span class="stat-icon blue"><?= icono('inventario') ?></span><div><p><?= escapar($nombre) ?></p><strong><?= (int) $datos[$campo] ?></strong><small><?= escapar($detalle) ?></small></div></article><?php endforeach; ?>
</section>
<section class="panel"><div class="panel-header"><div><h2>Inventario por sucursal</h2><p class="muted">Catálogo compartido, cantidades independientes por sede</p></div><div class="heading-actions"><?php if (puede('inventario')) : ?><button class="btn btn-light" type="button" data-open="form-stock">Existencias</button><?php endif; ?><?php if (puede('productos')) : ?><button class="btn btn-primary" type="button" data-open="form-producto">Nuevo producto</button><?php endif; ?></div></div>
<div class="table-wrap"><table><thead><tr><th scope="col">Producto</th><th scope="col">Categoría</th><th scope="col">Precio</th><th scope="col">Mínimo</th><?php foreach ($sucursalesVisibles as $s) : ?><th scope="col"><?= escapar($s['nombre']) ?></th><?php endforeach; ?><th scope="col">Estado del producto</th><th scope="col">Acciones</th></tr></thead><tbody>
<?php foreach ($datos['productos'] as $p) : ?><tr><td><?= escapar($p['nombre']) ?><small><?= escapar(folio('PROD', $p['id_producto'])) ?></small></td><td><?= escapar($p['categoria']) ?></td><td><?= moneda($p['precio']) ?></td><td><?= (int) $p['stock_minimo'] ?></td>
<?php foreach ($sucursalesVisibles as $s) : ?><?php $cantidad = $datos['stock'][$p['id_producto']][$s['id_sucursal']] ?? null; ?><td><span class="<?= $cantidad !== null && $cantidad < (int) $p['stock_minimo'] ? 'stock-warning' : '' ?>"><?= $cantidad === null ? '—' : $cantidad ?></span></td><?php endforeach; ?>
<td><span class="status <?= $p['activo'] ? 'status-ready' : 'status-inactive' ?>"><?= $p['activo'] ? 'Activo' : 'Inactivo' ?></span></td><td><?php botonEditar("form-producto", $p, "id_producto"); ?></td></tr><?php endforeach; ?>
<?php if ($datos['productos'] === []) : ?><tr><td colspan="<?= 6 + count($sucursalesVisibles) ?>" class="empty-cell">No se encontraron productos.</td></tr><?php endif; ?>
</tbody></table></div><p class="panel-note">“—” indica que no existe un registro de inventario para esa combinación de producto y sucursal. Las cantidades bajo el mínimo se destacan en ámbar.</p></section>
<section class="panel"><div class="panel-header"><div><h2>Categorías</h2><p class="muted">Clasificación del catálogo de productos</p></div><?php if (puede('categorias')) : ?><button class="btn btn-primary" type="button" data-open="form-categoria">Nueva categoría</button><?php endif; ?></div>
<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Descripción</th><th>Acciones</th></tr></thead><tbody>
<?php foreach ($catalogos['categorias'] as $c) : ?><tr><td><?= escapar($c['nombre']) ?></td><td class="text-cell"><?= escapar($c['descripcion'] ?: '—') ?></td><td><?php botonEditar('form-categoria', $c, 'id_categoria'); ?></td></tr><?php endforeach; ?>
<?php if ($catalogos['categorias'] === []) : ?><tr><td colspan="3" class="empty-cell">No hay categorías registradas.</td></tr><?php endif; ?>
</tbody></table></div></section>
